const cfg = $json.config;
const body = $json.body ?? {};
const data = body.data ?? {};
const key = data.key ?? {};
const jid = typeof key.remoteJid === 'string' ? key.remoteJid : '';
let message = data.message ?? {};
let unsupportedWrapper = false;
for (let depth = 0; depth < 4; depth++) {
  if (message.viewOnceMessage || message.viewOnceMessageV2 || message.viewOnceMessageV2Extension) {
    unsupportedWrapper = true;
    break;
  }
  if (message.ephemeralMessage?.message) message = message.ephemeralMessage.message;
  else if (message.documentWithCaptionMessage?.message) message = message.documentWithCaptionMessage.message;
  else break;
}
const image = message.imageMessage;
const audio = message.audioMessage;
const documentMime = message.documentMessage?.mimetype;
const document = typeof documentMime === 'string' && documentMime.toLowerCase().split(';')[0].trim() === 'application/pdf'
  ? message.documentMessage : null;
const textValue = message.conversation ?? message.extendedTextMessage?.text;
const kind = image || document ? 'receipt' : audio ? 'voice' : typeof textValue === 'string' ? 'text' : 'unsupported';
const text = typeof textValue === 'string' ? textValue.trim() : '';
const media = image ?? document ?? audio;
const rawTime = data.messageTimestamp;
const timestamp = typeof rawTime === 'number' ? rawTime
  : typeof rawTime === 'string' && /^\d+$/.test(rawTime) ? Number(rawTime) : NaN;
const validTime = Number.isSafeInteger(timestamp) && timestamp > 0 && timestamp < 253402300800;
const context = media?.contextInfo ?? message.extendedTextMessage?.contextInfo;
const command = kind !== 'text' ? 'expense'
  : /^\/(help|info|start)(?:\s|$)/i.test(text) ? 'help'
  : /^\/(laporan|reportpdf)(?:\s|$)/i.test(text) ? 'report'
  : /^Halo Cashly, hubungkan WhatsApp saya\. Kode koneksi:\s*\S+/i.test(text) ? 'link'
  : 'expense_or_correction';
let reason = null;
if (body.event !== 'messages.upsert') reason = 'event_not_supported';
else if (body.instance !== cfg.expected_instance) reason = 'wrong_instance';
else if (key.fromMe !== false) reason = 'not_inbound';
else if (!/^\d+(?::\d+)?@(s\.whatsapp\.net|lid)$/.test(jid)) reason = 'not_direct_chat';
else if (typeof key.id !== 'string' || !key.id || key.id.length > 255) reason = 'invalid_message_id';
else if (!validTime) reason = 'invalid_timestamp';
else if (body.type === 'history' || data.type === 'append' || data.isHistory === true) reason = 'history';
else if (unsupportedWrapper) reason = 'view_once_not_supported';
else if (kind === 'unsupported' || (kind === 'text' && !text)) reason = 'unsupported_or_empty';
else if (text.length > 4000 || (typeof media?.caption === 'string' && media.caption.length > 1000)) reason = 'input_too_long';
const phoneJid = [jid, key.remoteJidAlt].find(v => typeof v === 'string' && /^\d+@s\.whatsapp\.net$/.test(v)) ?? null;
return {json: {
  config: cfg,
  eligible: reason === null,
  ignore_reason: reason,
  event: {
    contract_version: 'cashly-wa-v1', environment: 'staging', provider: 'evolution',
    bot_id: cfg.expected_instance, event_type: 'messages.upsert',
    message_id: typeof key.id === 'string' ? key.id : '', sender_id: jid,
    sender_phone_jid: phoneJid, addressing_mode: typeof key.addressingMode === 'string' ? key.addressingMode : null,
    sent_at: validTime ? new Date(timestamp * 1000).toISOString() : null,
    received_at: new Date().toISOString(), kind, command_hint: command,
    text: kind === 'text' ? text : null,
    caption: kind === 'receipt' && typeof media?.caption === 'string' ? media.caption : null,
    quoted_message_id: typeof context?.stanzaId === 'string' ? context.stanzaId : null,
    media: media ? {mime_type: typeof media.mimetype === 'string' ? media.mimetype : null} : null
  }
}};

const original = $('Normalisasi Pesan').item.json;
const result = $json.data;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!result || !uuid.test(result.event_id ?? '') || !['reply','process','ignore'].includes(result.action)) {
  throw new Error('CASHLY_ADMISSION_INVALID');
}
if (result.message_id !== original.event.message_id || result.sender_id !== original.event.sender_id || result.bot_id !== original.event.bot_id) {
  throw new Error('CASHLY_EVENT_SCOPE_MISMATCH');
}
if (result.action === 'process' && (result.verified_link !== true || !uuid.test(result.job_id ?? '') || result.kind !== original.event.kind)) {
  throw new Error('CASHLY_PROCESS_NOT_AUTHORIZED');
}
if (result.action === 'process' && original.config.expense_processing_enabled !== true) {
  throw new Error('CASHLY_EXPENSE_PROCESSING_DISABLED');
}
if (result.action === 'reply' && (!uuid.test(result.reply?.id ?? '') || typeof result.reply?.text !== 'string' || !result.reply.text.trim() || result.reply.text.length > 4000)) {
  throw new Error('CASHLY_REPLY_INVALID');
}
return {json: {
  config: original.config, event: original.event,
  admission: {event_id: result.event_id, action: result.action,
    job_id: result.action === 'process' ? result.job_id : null,
    kind: original.event.kind, verified_link: result.verified_link === true},
  reply: result.action === 'reply' ? {id: result.reply.id, text: result.reply.text} : null
}};

const original = $('Validasi Izin Backend').item.json;
const receipt = original.event.kind === 'receipt';
const result = $json;
const payload = result.data;
const mime = typeof payload?.mimetype === 'string' ? payload.mimetype.toLowerCase().split(';')[0].trim() : '';
const base64 = payload?.base64;
const maxBytes = receipt ? 10 * 1024 * 1024 : 5 * 1024 * 1024;
const pdf = receipt && original.event.media?.mime_type?.toLowerCase().split(';')[0].trim() === 'application/pdf';
const allowed = pdf ? ['application/pdf'] : receipt ? ['image/jpeg','image/png','image/webp']
  : ['audio/ogg','audio/opus','audio/webm','audio/mp4','audio/m4a','audio/x-m4a','audio/aac','audio/mpeg','audio/mp3','audio/wav','audio/x-wav','audio/flac','audio/x-flac'];
let issue = null;
if (result.success !== true || !payload) issue = 'MEDIA_FETCH_FAILED';
else if (!allowed.includes(mime)) issue = 'MEDIA_TYPE_UNSUPPORTED';
else if (typeof base64 !== 'string' || !base64 || base64.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(base64)) issue = 'MEDIA_BASE64_INVALID';
else {
  const padding = base64.endsWith('==') ? 2 : base64.endsWith('=') ? 1 : 0;
  if (base64.length / 4 * 3 - padding > maxBytes) issue = 'MEDIA_TOO_LARGE';
}
return {json: {
  config: original.config, event: original.event, admission: original.admission,
  process_body: {
    event_id: original.admission.event_id, kind: original.event.kind,
    media: issue ? null : {mime_type: mime, data: base64}, input_error: issue
  }
}};

const original = $('Validasi Izin Backend').item.json;
const receipt = original.event.kind === 'receipt';
const result = $json;
const payload = result.data;
const mime = typeof payload?.mimetype === 'string' ? payload.mimetype.toLowerCase().split(';')[0].trim() : '';
const base64 = payload?.base64;
const maxBytes = receipt ? 10 * 1024 * 1024 : 5 * 1024 * 1024;
const pdf = receipt && original.event.media?.mime_type?.toLowerCase().split(';')[0].trim() === 'application/pdf';
const allowed = pdf ? ['application/pdf'] : receipt ? ['image/jpeg','image/png','image/webp']
  : ['audio/ogg','audio/opus','audio/webm','audio/mp4','audio/m4a','audio/x-m4a','audio/aac','audio/mpeg','audio/mp3','audio/wav','audio/x-wav','audio/flac','audio/x-flac'];
let issue = null;
if (result.success !== true || !payload) issue = 'MEDIA_FETCH_FAILED';
else if (!allowed.includes(mime)) issue = 'MEDIA_TYPE_UNSUPPORTED';
else if (typeof base64 !== 'string' || !base64 || base64.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(base64)) issue = 'MEDIA_BASE64_INVALID';
else {
  const padding = base64.endsWith('==') ? 2 : base64.endsWith('=') ? 1 : 0;
  if (base64.length / 4 * 3 - padding > maxBytes) issue = 'MEDIA_TOO_LARGE';
}
return {json: {
  config: original.config, event: original.event, admission: original.admission,
  process_body: {
    event_id: original.admission.event_id, kind: original.event.kind,
    media: issue ? null : {mime_type: mime, data: base64}, input_error: issue
  }
}};

const original = $('Validasi Izin Backend').item.json;
const result = $json.data;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!result || result.event_id !== original.admission.event_id || result.job_id !== original.admission.job_id
  || !['saved','needs_review','failed','queued','ignored'].includes(result.status)) throw new Error('CASHLY_OUTCOME_INVALID');
if (result.status === 'saved' && result.committed !== true) throw new Error('CASHLY_COMMIT_NOT_CONFIRMED');
const reply = result.reply;
if (reply != null && (!uuid.test(reply.id ?? '') || typeof reply.text !== 'string' || !reply.text.trim() || reply.text.length > 4000)) throw new Error('CASHLY_REPLY_INVALID');
if (['saved','needs_review','failed'].includes(result.status) && !reply) throw new Error('CASHLY_TERMINAL_REPLY_MISSING');
return {json: {config: original.config, event: original.event, admission: original.admission,
  status: result.status, reply: reply ? {id: reply.id, text: reply.text} : null}};

const original = $('Balasan yang Diklaim').item.json;
const response = $json;
const id = response.data?.key?.id;
const accepted = response.success === true && typeof id === 'string' && id.length > 0 && response.data?.key?.fromMe === true;
return {json: {config: original.config,
  delivery: {
    contract_version: 'cashly-wa-v1', environment: 'staging', provider: 'evolution',
    bot_id: original.event.bot_id, event_id: original.admission.event_id,
    reply_id: original.reply.id, recipient_id: original.event.sender_id,
    lease_id: original.reply.lease_id,
    status: accepted ? 'accepted' : 'unknown', outbound_message_id: accepted ? id : null,
    error_code: accepted ? null : 'OUTBOUND_UNCONFIRMED'
  }
}};

const request = $('Siapkan Klaim').item.json;
const value = $json.data;
if (value === null) return {json: {has_claim: false}};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!value || !uuid.test(value.event_id ?? '') || value.bot_id !== request.config.expected_instance
  || value.action !== 'reply' || !/^\d+(?::\d+)?@(s\.whatsapp\.net|lid)$/.test(value.sender_id ?? '')
  || !uuid.test(value.reply?.id ?? '') || !uuid.test(value.reply?.lease_id ?? '')
  || typeof value.reply.text !== 'string' || !value.reply.text.trim() || value.reply.text.length > 4000) {
  throw new Error('CASHLY_OUTBOX_CLAIM_INVALID');
}
if (request.requested_reply_id && (request.requested_reply_id !== value.reply.id
  || request.expected_event?.sender_id !== value.sender_id
  || request.expected_event?.message_id !== value.message_id)) throw new Error('CASHLY_OUTBOX_SCOPE_MISMATCH');
if (value.reply.report_pdf === true && value.verified_link !== true) throw new Error('CASHLY_REPORT_SCOPE_MISMATCH');
return {json: {
  has_claim: true, config: request.config,
  event: {bot_id: value.bot_id, sender_id: value.sender_id, message_id: value.message_id, kind: value.kind},
  admission: {event_id: value.event_id}, reply: value.reply
}};
